namespace ghidra.framework.main;








using docking;
using docking;
using docking.framework;
using docking.widgets.label;
using generic.application;
using generic.theme;
using ghidra.framework;
using ghidra.util;
using ghidra.util;
using ghidra.util.layout;
using resources;
using utilities.util;
using utility.application;

public class UserAgreementDialog : DialogComponentProvider {
	private static readonly string USER_AGREEMENT_FILENAME = "UserAgreement.html";
	private static readonly string FONT_ID = "font.user.agreement";
	private bool exitOnCancel;

	public UserAgreementDialog(bool showAgreementChoices, bool exitOnCancel) : base("", true, false, true, false)
    {
		this.exitOnCancel = exitOnCancel;
		addWorkPanel(buildWorkPanel());
		addOKButton();
		if (showAgreementChoices) {
			setOkButtonText("I Agree");
			addCancelButton();
			setCancelButtonText("I Don't Agree");
		}
		else {
			setOkButtonText("OK");
		}
		setPreferredSize(1000, 500);
	}

	private JComponent buildWorkPanel() {
		JPanel panel = new JPanel(new BorderLayout());
		JLabel label = new GDLabel("Ghidra User Agreement", SwingConstants.CENTER);
		label.setBorder(BorderFactory.createEmptyBorder(0, 0, 10, 0));
		label.getAccessibleContext().setAccessibleName("Ghidra User Agreement");
		Gui.registerFont(label, FONT_ID);
		panel.add(label, BorderLayout.NORTH);
		panel.setBorder(BorderFactory.createEmptyBorder(10, 40, 40, 40));
		JEditorPane editorPane = new JEditorPane();
		editorPane.setEditorKit(new HTMLEditorKit());
		editorPane.setMargin(new Insets(10, 10, 10, 10));
		editorPane.getAccessibleContext().setAccessibleName("Agreement");
		editorPane.setText(getUserAgreementText());
		editorPane.setCaretPosition(0);
		editorPane.setEditable(false);

		JScrollPane scrollPane = new JScrollPane(editorPane);
		scrollPane.getAccessibleContext().setAccessibleName("Editor");
		panel.add(scrollPane, BorderLayout.CENTER);
		JPanel checkBoxPanel = new JPanel(new VerticalLayout(10));
		checkBoxPanel.setBorder(BorderFactory.createEmptyBorder(5, 10, 0, 10));
		checkBoxPanel.getAccessibleContext().setAccessibleName("Checkbox");
		panel.add(checkBoxPanel, BorderLayout.SOUTH);
		panel.getAccessibleContext().setAccessibleName("User Agreement");
		return panel;
	}

	private string getUserAgreementText() {
		try
{
    using (InputStream @in = ResourceManager.getResourceAsStream(USER_AGREEMENT_FILENAME))
    {

			string text = FileUtilities.getText(@in);
			if (!HTMLUtilities.isHTML(text)) {
				// our labels to not render correctly when not using HTML
				text = HTMLUtilities.toHTML(text);
			}

			text = text.replace('\n', ' ');

			return text;
		
    }
}
		catch (Exception e) {
			// use default splash screen info
			Msg.debug(this, "Unable to read user agreement text from: " + USER_AGREEMENT_FILENAME);
			return USER_AGREEMENT_FILENAME + " file is missing!";
		}
	}

	/* @Override */
	protected void okCallback() {
		close();
	}

	/* @Override */
	protected void cancelCallback() {
		if (exitOnCancel) {
			Environment.Exit(0);
		}
		close();
	}

	public static void main(string[] args)
    {
		ApplicationLayout layout = new GenericApplicationLayout("User Agreement Main", "1.0");
		DockingApplicationConfiguration config = new DockingApplicationConfiguration();
		Application.initializeApplication(layout, config);
		UserAgreementDialog dialog = new UserAgreementDialog(true, true);
		DockingWindowManager.showDialog(null, dialog);
	}
}
